INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/02/2026', 'Carnaval', 'FACULTATIVO', 'Carnaval NÃO é um feriado oficial, é Ponto Facultativo, ou seja, cabe às empresas e orgão públicos decidirem se trabalharão ou não.', null, null);
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('17/02/2026', 'Terça de Carnaval (Comércio de Fortaleza)', 'FACULTATIVO', 'Esta data (17/02) refere-se ao feriado dos trabalhadores do comércio de Fortaleza/CE, conforme a Lei Municipal nº 5.913/1985 (ou 1991 em consolidações posteriores). Para as demais cidades e setores, a data é ponto facultativo.', null, null);
