INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('02/04/2026', 'Quinta-feira Santa', 'FACULTATIVO', 'Ponto facultativo que antecede a Sexta-feira da Paixão, marcando o encerramento da Quaresma e o início do Tríduo Pascal na tradição cristã.', null, null);
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('04/06/2026', 'Corpus Christi', 'FACULTATIVO', 'Ponto Facultativo no País, mas Feriado Municipal em algumas cidades.. Corpus Christi, expressão latina que significa Corpo de Cristo, é uma festa Cristã realizada na quinta-feira seguinte ao domingo da Santíssima Trindade.', null, null);
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('26/07/2026', 'Fundação da Cidade de Goiás', 'FACULTATIVO', 'Feriado para Servidores Públicos. Determinado pelo Estatuto dos Funcionários Públicos Civis do Estado de Goiás e de suas Autarquias, Lei nº 10.460, de 22 de fevereiro de 1988', 'GO', '5208905');
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/10/2026', 'Dia do Professor', 'FACULTATIVO', 'FERIADO ESCOLAR - No dia 15 de outubro de 1827 (dia consagrado à educadora Santa Teresa de Ávila), o Imperador do Brasil, Pedro I, baixou um Decreto Imperial que criou o Ensino Elementar no Brasil. Pelo decreto, "todas as cidades, vilas e lugarejos teriam suas escolas de primeiras letras"', null, null);
