INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/10/2026', 'Dia do Servidor Público', 'FACULTATIVO', 'Dia do Servidor Público - art. 249 da Lei Municipal nº 2.215/1991. O dia do servidor público é feriado apenas para funcionários públicos.', null, null);
